.sx-field-label { font: 500 11px/1.2 var(--sx-ui); color: var(--sx-dim); margin-top: 4px; }

.sx-conn { border: 1px solid var(--sx-line); border-radius: 8px; padding: 10px 12px; background: rgba(8, 12, 17, 0.6); display: flex; flex-direction: column; gap: 8px; }
.sx-conn-head { display: flex; align-items: center; justify-content: space-between; }
