.sx-step-title { flex: 1; min-width: 0; }
.sx-step-title h4 { margin: 0 0 3px; color: var(--sx-text); font-size: 12px; letter-spacing: 0.02em; text-transform: none; }
.sx-step-title p { font-size: 11px; }
.sx-step-state { font: 600 10px/1 var(--sx-display); color: var(--sx-dim); white-space: nowrap; padding-top: 4px; }
.sx-step-state.done { color: var(--sx-ok); }
.sx-step-state.review { color: var(--sx-amber); }
.sx-actions { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.sx-actions > .sx-dim { font-size: 11px; }

.sx-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.sx-pair figure { margin: 0; display: flex; flex-direction: column; gap: 4px; }
.sx-pair figcaption { font-size: 11px; }
.sx-pair img { width: 100%; aspect-ratio: 1; object-fit: contain; border-radius: 6px; background: radial-gradient(circle at 50% 40%, #16212d, #070b10); border: 1px solid var(--sx-line); }
.sx-pair-empty { display: block; aspect-ratio: 1; border-radius: 6px; border: 1px dashed var(--sx-line-hi); }

.sx-describe { display: flex; flex-direction: column; gap: 8px; }
.sx-subject-input {
  width: 100%; resize: vertical; font: 400 12px/1.5 var(--sx-ui); color: var(--sx-text);
  background: #0a1017; border: 1px solid var(--sx-line-hi); border-radius: 6px; padding: 8px; min-height: 96px;
}
.sx-rules { display: flex; flex-direction: column; gap: 3px; font-size: 11px; color: var(--sx-dim); padding: 8px 10px; border-left: 2px solid var(--sx-cyan); background: rgba(95, 212, 255, 0.04); }
.sx-rules p { margin: 0; }
.sx-rules span { color: var(--sx-cyan); font-weight: 700; margin-right: 4px; }

.sx-job { border: 1px solid var(--sx-line); border-radius: 8px; padding: 10px 12px; background: rgba(8, 12, 17, 0.7); display: flex; flex-direction: column; gap: 8px; }
.sx-job-head { display: flex; align-items: center; gap: 8px; }
.sx-job-head h4 { margin: 0; flex: 1; color: var(--sx-text); font-size: 12px; letter-spacing: 0.02em; text-transform: none; }
.sx-job-time { font: 600 12px/1 var(--sx-display); color: var(--sx-cyan); font-variant-numeric: tabular-nums; }
.sx-job-stages { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 3px; font-size: 11px; color: var(--sx-dim); }
.sx-job-stages li.ok { color: var(--sx-ok); }
.sx-job-stages li.bad { color: var(--sx-err); }
.sx-job-stages li.now { color: var(--sx-amber); }
.sx-log {
  margin: 0; max-height: 180px; overflow: auto; font: 11px/1.45 Consolas, "Cascadia Mono", monospace; color: #b7cbda;
  background: #05080c; border: 1px solid var(--sx-line); border-radius: 6px; padding: 8px; white-space: pre-wrap; overflow-wrap: anywhere;
}

/* the viewport's loading state: a small glass readout with an indeterminate bar (still under reduced motion) */
.sx-loading {
  position: absolute; right: 12px; top: 12px; z-index: 3; display: flex; align-items: center; gap: 10px;
  padding: 7px 10px; border-radius: 6px; background: rgba(12, 17, 24, 0.85); border: 1px solid var(--sx-line-hi);
  font: 500 12px/1 var(--sx-ui); color: var(--sx-text);
}
.sx-loading i { position: relative; width: 64px; height: 3px; border-radius: 2px; background: var(--sx-line); overflow: hidden; }
.sx-loading i::after {
  content: ""; position: absolute; inset: 0; width: 30%; background: var(--sx-amber); box-shadow: 0 0 8px var(--sx-amber);
  animation: sx-sweep 1.1s ease-in-out infinite;
}
@keyframes sx-sweep { from { transform: translateX(-100%); } to { transform: translateX(340%); } }
@media (prefers-reduced-motion: reduce) { .sx-loading i::after { animation: none; width: 100%; opacity: 0.5; } }

/* The Audio workspace (TICKET-08a): a thin bar above the sound library, in the Studio's dark telemetry look */
.sx-audio-pane { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.sx-audio-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 14px;
  background: var(--sx-panel);
  border-bottom: 1px solid var(--sx-line);
}
.sx-audio-bar p { margin: 0; flex: 1; font: 500 12px/1.4 Inter, system-ui, sans-serif; color: var(--sx-dim); }
.sx-audio-bar button {
  font: 600 11px/1 Oxanium, sans-serif;
  letter-spacing: 0.06em;
  padding: 7px 12px;
  background: var(--sx-raise);
  color: #3dc8ff;
  border: 1px solid rgba(61, 200, 255, 0.45);
  border-radius: 4px;
  cursor: pointer;
}
.sx-audio-bar button:hover:not(:disabled) { border-color: #3dc8ff; background: rgba(61, 200, 255, 0.14); }
.sx-audio-bar button:disabled { opacity: 0.4; cursor: default; }
.sx-audio-pane > .sx-banner { margin: 0; }

